using System.Net;
using System.Text;
using System.Text.Json;
namespace Arcoll.WinUI3.Services.BackupCenter;
public sealed class BackupRemoteException(string message,int status):IOException(message){public int Status=>status;}
public sealed class BackupHttpClient:IBackupRemote
{
 private readonly HttpClient _http;private readonly BackupIdentity _identity;private readonly Uri _endpoint;
 public BackupHttpClient(BackupIdentity identity,HttpMessageHandler? handler=null){if(!Uri.TryCreate(identity.Origin.TrimEnd('/')+"/api/backup.php",UriKind.Absolute,out var endpoint)||endpoint.Scheme!="https"||endpoint.UserInfo.Length>0||endpoint.Fragment.Length>0)throw new ArgumentException("Origem HTTPS inválida.");_identity=identity;_endpoint=endpoint;_http=new HttpClient(handler??new HttpClientHandler{AllowAutoRedirect=false,UseProxy=false}){Timeout=TimeSpan.FromSeconds(150)};}
 private HttpRequestMessage Request(string action,object? body){var request=new HttpRequestMessage(HttpMethod.Post,new Uri(_endpoint+"?action="+action));request.Headers.TryAddWithoutValidation("X-Arcoll-Fingerprint",_identity.Fingerprint);request.Headers.TryAddWithoutValidation("X-Arcoll-Site-Code",_identity.SiteCode);request.Headers.TryAddWithoutValidation("X-Arcoll-Key",_identity.Key);request.Headers.TryAddWithoutValidation("User-Agent","TIDigital-BackupCenter/1.0");request.Headers.TryAddWithoutValidation("Accept","application/json");request.Content=new StringContent(JsonSerializer.Serialize(body??new{},BackupJson.Options),new UTF8Encoding(false),"application/json");request.Content.Headers.ContentType=new System.Net.Http.Headers.MediaTypeHeaderValue("application/json");return request;}
 private async Task<JsonElement> JsonAsync(string action,object body,CancellationToken ct,Func<HttpRequestMessage>? factory=null){for(var attempt=0;;attempt++){
  using var request=factory?.Invoke()??Request(action,body);try{using var response=await _http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,ct);if((int)response.StatusCode==429||(int)response.StatusCode>=500){if(attempt<3){var wait=response.Headers.RetryAfter?.Delta??TimeSpan.FromSeconds(Math.Pow(2,attempt+1));await Task.Delay(TimeSpan.FromSeconds(Math.Clamp(wait.TotalSeconds,1,60)),ct);continue;}}
   await using var input=await response.Content.ReadAsStreamAsync(ct);using var buffer=new MemoryStream();var bytes=new byte[65536];int read;while((read=await input.ReadAsync(bytes,ct))>0){if(buffer.Length+read>33554432)throw new IOException("Resposta acima do limite seguro.");buffer.Write(bytes,0,read);}JsonDocument doc;try{doc=JsonDocument.Parse(buffer.ToArray());}catch(JsonException){throw new BackupRemoteException("Resposta inválida da plataforma (HTTP "+(int)response.StatusCode+").",(int)response.StatusCode);}using(doc){var root=doc.RootElement;if(!response.IsSuccessStatusCode||!root.TryGetProperty("ok",out var ok)||ok.ValueKind!=JsonValueKind.True){var error=root.TryGetProperty("error",out var message)&&message.ValueKind==JsonValueKind.String?message.GetString()??"Falha na plataforma.":"Falha na plataforma.";throw new BackupRemoteException(error,(int)response.StatusCode);}return root.Clone();}
  }catch(HttpRequestException)when(attempt<3){await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2,attempt+1)),ct);}catch(TaskCanceledException)when(!ct.IsCancellationRequested&&attempt<3){await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2,attempt+1)),ct);}
 }}
 public Task<JsonElement> CallAsync(string action,object body,CancellationToken ct)=>JsonAsync(action,body,ct);
 public async Task<BackupOperation?> NextAsync(string runner,CancellationToken ct){var r=await JsonAsync("agent-next",new{runner},ct);return r.GetProperty("operation").ValueKind==JsonValueKind.Null?null:r.GetProperty("operation").Deserialize<BackupOperation>(BackupJson.Options);}
 public Task<JsonElement> StateAsync(CancellationToken ct)=>JsonAsync("agent-state",new{},ct);
 public async Task ProgressAsync(BackupOperation op,BackupSummary summary,CancellationToken ct)=>_ =await JsonAsync("agent-progress",new{run_id=op.Id,lease=op.Lease,summary},ct);
 public async Task<UploadReply> BeginAsync(BackupOperation op,string digest,string md5,long size,CancellationToken ct)=>(await JsonAsync("agent-begin",new{run_id=op.Id,lease=op.Lease,digest,md5,size},ct)).Deserialize<UploadReply>(BackupJson.Options)??throw new IOException("Envio não confirmado.");
 public async Task<UploadReply> ChunkAsync(BackupOperation op,string digest,string md5,string upload,long offset,byte[] data,CancellationToken ct){var hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(data)).ToLowerInvariant();return (await JsonAsync("agent-chunk",new{},ct,()=>{var request=Request("agent-chunk",null);request.Content?.Dispose();request.Content=new ByteArrayContent(data);request.Content.Headers.ContentType=new System.Net.Http.Headers.MediaTypeHeaderValue("application/octet-stream");foreach(var field in new Dictionary<string,string>{{"Run",op.Id},{"Lease",op.Lease},{"Digest",digest},{"Md5",md5},{"Upload",upload},{"Offset",offset.ToString(System.Globalization.CultureInfo.InvariantCulture)},{"Sha256",hash}})request.Headers.TryAddWithoutValidation("X-Backup-"+field.Key,field.Value);return request;})).Deserialize<UploadReply>(BackupJson.Options)??throw new IOException("Bloco não confirmado.");}
 public async Task FilesAsync(BackupOperation op,IReadOnlyList<BackupFile> files,CancellationToken ct)=>_=await JsonAsync("agent-files",new{run_id=op.Id,lease=op.Lease,files},ct);
 public async Task<FinishReply> FinishAsync(BackupOperation op,BackupSummary summary,CancellationToken ct)=>(await JsonAsync("agent-finish",new{run_id=op.Id,lease=op.Lease,summary},ct)).Deserialize<FinishReply>(BackupJson.Options)??throw new IOException("Ponto não confirmado.");
 public async Task FailAsync(BackupOperation op,BackupSummary summary,CancellationToken ct)=>_=await JsonAsync("agent-fail",new{run_id=op.Id,lease=op.Lease,summary},ct);
 public async Task<ManifestReply> ManifestAsync(BackupOperation op,CancellationToken ct)=>(await JsonAsync("agent-manifest",new{run_id=op.Id,lease=op.Lease},ct)).Deserialize<ManifestReply>(BackupJson.Options)??throw new IOException("Manifesto indisponível.");
 public async Task<Stream> DownloadAsync(BackupOperation op,BackupFile file,CancellationToken ct){using var request=Request("agent-download",new{run_id=op.Id,lease=op.Lease,path_hash=file.PathHash});var response=await _http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,ct);if(!response.IsSuccessStatusCode){var status=(int)response.StatusCode;response.Dispose();throw new BackupRemoteException("Não foi possível ler o objeto de backup (HTTP "+status+").",status);}return new ResponseStream(await response.Content.ReadAsStreamAsync(ct),response);}
 public async Task FinishOperationAsync(BackupOperation op,BackupSummary summary,CancellationToken ct)=>_=await JsonAsync("agent-finish-operation",new{run_id=op.Id,lease=op.Lease,summary},ct);
 public void Dispose()=>_http.Dispose();
 private sealed class ResponseStream(Stream stream,HttpResponseMessage response):Stream{public override bool CanRead=>true;public override bool CanSeek=>false;public override bool CanWrite=>false;public override long Length=>throw new NotSupportedException();public override long Position{get=>throw new NotSupportedException();set=>throw new NotSupportedException();}public override int Read(byte[] buffer,int offset,int count)=>stream.Read(buffer,offset,count);public override ValueTask<int> ReadAsync(Memory<byte> buffer,CancellationToken ct=default)=>stream.ReadAsync(buffer,ct);public override void Flush(){}public override long Seek(long offset,SeekOrigin origin)=>throw new NotSupportedException();public override void SetLength(long value)=>throw new NotSupportedException();public override void Write(byte[] buffer,int offset,int count)=>throw new NotSupportedException();protected override void Dispose(bool disposing){if(disposing){stream.Dispose();response.Dispose();}base.Dispose(disposing);}}
}
